<script setup lang="ts">
import{onMounted,ref}from'vue';import{storeToRefs}from'pinia';import FinanceSubnav from'../components/FinanceSubnav.vue';import FinanceScenarioBar from'../components/FinanceScenarioBar.vue';import{useFinanceStore}from'../runtime/finance-store';import'./finance-views.css'
const store=useFinanceStore();const{channels,loading,error,scenario,actor}=storeToRefs(store),actionError=ref('');async function apply(id:string){actionError.value='';if(!confirm('这里只会创建本地“原型模拟申请”，不会向第三方发送资料。是否继续？'))return;try{await store.applyChannel(id)}catch(e){actionError.value=e instanceof Error?e.message:'提交失败'}}onMounted(()=>store.loadChannels())
</script>
<template><section class="finance-page"><header class="finance-header"><div><h1>在线支付设置</h1><p>固定通道展示；本原型不收集商户密钥、证书、身份证或真实银行卡资料。</p></div><FinanceScenarioBar :scenario="scenario" :role="actor.role" @scenario="async v=>{await store.setScenario(v);await store.loadChannels()}" @role="async v=>{await store.setRole(v);await store.loadChannels()}"/></header><FinanceSubnav/><p class="finance-warning"><strong>原型边界：</strong>“开通”只产生本地模拟申请，通道仍保持未开通，不发网络请求、不创建支付账户、不改变余额。</p><p v-if="actionError||error" class="finance-warning">{{actionError||error}}</p><div v-if="loading" class="finance-state">正在加载支付通道…</div><div v-else-if="!channels.length" class="finance-state">暂无支付通道资料</div><div v-else class="payment-grid"><article v-for="channel in channels" :key="channel.id" class="payment-card"><span class="fin-status" :class="channel.application?.status??channel.status">{{channel.application?'模拟申请中':channel.status==='opened'?'已开通':'未开通'}}</span><h2>{{channel.name}}</h2><p>{{channel.description}}</p><p v-if="channel.application" class="prototype">本地原型模拟申请已记录于 {{channel.application.createdAt.slice(0,16).replace('T',' ')}}；未提交到第三方。</p><button v-if="channel.status==='unopened'&&!channel.application" class="fin-button primary" @click="apply(channel.id)">提交原型模拟申请</button><button v-else class="fin-button" disabled>{{channel.application?'模拟处理中':'已开通'}}</button></article></div></section></template>
